import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import './Booking.css';

const eventTypes = [
  'Batch Party',
  'Social Gathering',
  'Birthday Party',
  'Cultural Event',
  'Other Event'
];

const Booking = () => {
  const location = useLocation();
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    eventType: '',
    date: '',
    message: ''
  });
  const [submitted, setSubmitted] = useState(false);

  useEffect(() => {
    if (location.state && location.state.eventType) {
      setForm(f => ({ ...f, eventType: location.state.eventType }));
    }
  }, [location.state]);

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = e => {
    e.preventDefault();
    // Placeholder: send form data to backend or show confirmation
    setSubmitted(true);
  };

  return (
    <div className="booking-bg">
      <div className="booking-container">
        <h1 className="booking-title">Book Your Event</h1>
        <p className="booking-desc">Fill out the form below to book your event with us. We’ll get back to you as soon as possible!</p>
        {submitted ? (
          <div className="booking-success">Thank you for your booking! We will contact you soon.</div>
        ) : (
          <form className="booking-form" onSubmit={handleSubmit}>
            <div className="booking-form-group">
              <label htmlFor="name">Name</label>
              <input type="text" id="name" name="name" value={form.name} onChange={handleChange} required />
            </div>
            <div className="booking-form-group">
              <label htmlFor="email">Email</label>
              <input type="email" id="email" name="email" value={form.email} onChange={handleChange} required />
            </div>
            <div className="booking-form-group">
              <label htmlFor="phone">Phone</label>
              <input type="tel" id="phone" name="phone" value={form.phone} onChange={handleChange} required pattern="[0-9]{10,15}" />
            </div>
            <div className="booking-form-group">
              <label htmlFor="eventType">Event Type</label>
              <select id="eventType" name="eventType" value={form.eventType} onChange={handleChange} required>
                <option value="">Select event type</option>
                {eventTypes.map(type => (
                  <option key={type} value={type}>{type}</option>
                ))}
              </select>
            </div>
            <div className="booking-form-group">
              <label htmlFor="date">Event Date</label>
              <input type="date" id="date" name="date" value={form.date} onChange={handleChange} required />
            </div>
            <div className="booking-form-group">
              <label htmlFor="message">Message</label>
              <textarea id="message" name="message" value={form.message} onChange={handleChange} rows={4} placeholder="Tell us more about your event..." />
            </div>
            <button className="booking-submit-btn" type="submit">Book Now</button>
          </form>
        )}
      </div>
    </div>
  );
};

export default Booking;
